import { AlertDialog } from '@refy-design/web';
import { Button } from '@refy-design/web';
import { DangerZone } from '@refy-design/web';
import { DangerZoneRow } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function DangerZoneExample() {
  const [open, setOpen] = useState(false),
    [deleted, setDeleted] = useState(false);
  return (
    <div style={stack}>
      {deleted ? (
        <>
          <p role="status">Sample account deleted in this session.</p>
          <Button onClick={() => setDeleted(false)}>Restore demo</Button>
        </>
      ) : (
        <DangerZone>
          <DangerZoneRow
            title="Delete sample account"
            description="This flow only removes the made-up data in this demo."
            actionLabel="Delete account"
            onConfirm={() => setOpen(true)}
          />
        </DangerZone>
      )}
      <AlertDialog
        open={open}
        onOpenChange={setOpen}
        title="Delete sample account?"
        destructive
        confirmLabel="Confirm deletion"
        onConfirm={() => {
          setDeleted(true);
          setOpen(false);
        }}
      >
        Only this demo will be reset. No real account is affected.
      </AlertDialog>
    </div>
  );
}
export function Example() {
  return <DangerZoneExample />;
}
